import * as step0 from './migrations/0017_margin_basis.mjs'

export const MIGRATIONS = [
  ["0001_core.sql", "-- 0001_core.sql — who the books belong to, who shares in them, who they trade\n-- with, and the counters that number the paper.\n--\n-- TWO LEVELS, deliberately not one. An ENTITY is a book-keeping unit: it has\n-- its own chart of accounts, its own document numbering and its own tax\n-- identity. A PROJECT is a brand, site or venture that earns and spends inside\n-- one entity — Mot Dang, wichaa, Amulet Atlas. Twenty projects under one\n-- entity means one set of books and twenty segment codes, not twenty ledgers.\n-- Moving a project to a new entity later is a field change, not a migration.\n\nCREATE TABLE entity (\n  id            TEXT PRIMARY KEY,\n  code          TEXT NOT NULL UNIQUE,          -- short, typed at a prompt: 'nan', 'thaico'\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  kind          TEXT NOT NULL\n                CHECK (kind IN ('sole','partnership','company','household','planned')),\n  -- 'planned' books an entity that does not legally exist yet. Costs incurred\n  -- before registration are real and someone paid them; they sit here until\n  -- the company forms and they can be settled or contributed as capital.\n  country       TEXT NOT NULL DEFAULT 'TH',\n  currency      TEXT NOT NULL DEFAULT 'THB',   -- functional currency of these books\n  tax_id        TEXT,                          -- 13-digit TIN when registered\n  vat_registered INTEGER NOT NULL DEFAULT 0,\n  vat_from      TEXT,                          -- YYYY-MM-DD, first VAT period\n  address_en    TEXT,\n  address_th    TEXT,\n  fiscal_year_end TEXT NOT NULL DEFAULT '12-31',  -- MM-DD\n  status        TEXT NOT NULL DEFAULT 'active'\n                CHECK (status IN ('active','dormant','closed')),\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\n\nCREATE TABLE project (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id),\n  code          TEXT NOT NULL UNIQUE,          -- 'motdang', 'wichaa', matches fleet.json ids\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  lane          TEXT,                          -- directory / service / product / study\n  url           TEXT,\n  status        TEXT NOT NULL DEFAULT 'live'\n                CHECK (status IN ('live','building','parked','retired')),\n  -- Which side of the household/company line this project's spending falls on.\n  -- Carried through to every journal line, so the split is a report.\n  cost_centre   TEXT NOT NULL DEFAULT 'company'\n                CHECK (cost_centre IN ('company','household')),\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\nCREATE INDEX idx_project_entity ON project(entity_id, status);\n\nCREATE TABLE person (\n  id            TEXT PRIMARY KEY,\n  code          TEXT NOT NULL UNIQUE,\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  locale        TEXT NOT NULL DEFAULT 'en' CHECK (locale IN ('en','th')),\n  email         TEXT,\n  line_user_id  TEXT,\n  tax_id        TEXT,\n  sso_number    TEXT,\n  status        TEXT NOT NULL DEFAULT 'active'\n                CHECK (status IN ('active','inactive')),\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\n\n-- What a person may DO in an entity's books. Capabilities are additive rows,\n-- as in the tasking board: read is the base state, everything else is granted.\nCREATE TABLE membership (\n  id            TEXT PRIMARY KEY,\n  person_id     TEXT NOT NULL REFERENCES person(id) ON DELETE CASCADE,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  role          TEXT NOT NULL\n                CHECK (role IN ('owner','partner','director','bookkeeper','staff','viewer')),\n  -- One row per capability keeps the grant legible in a list; a bitfield would\n  -- not survive being read aloud.\n  can_post      INTEGER NOT NULL DEFAULT 0,    -- write journals\n  can_issue     INTEGER NOT NULL DEFAULT 0,    -- issue invoices / receipts\n  can_pay       INTEGER NOT NULL DEFAULT 0,    -- record payments out\n  can_close     INTEGER NOT NULL DEFAULT 0,    -- close a period\n  can_see_pay   INTEGER NOT NULL DEFAULT 0,    -- payroll of other people\n  from_date     TEXT,\n  to_date       TEXT,\n  UNIQUE (person_id, entity_id)\n);\n\n-- A share in an entity, dated. Basis points, not percent: 3333 bp = 33.33%,\n-- and three equal partners add to 9999 with the remainder handled once at\n-- distribution rather than drifting through a float.\nCREATE TABLE holding (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  person_id     TEXT NOT NULL REFERENCES person(id) ON DELETE CASCADE,\n  share_bp      INTEGER NOT NULL CHECK (share_bp >= 0 AND share_bp <= 10000),\n  class         TEXT NOT NULL DEFAULT 'ordinary',\n  from_date     TEXT NOT NULL,\n  to_date       TEXT,                          -- NULL = current\n  note          TEXT\n);\nCREATE INDEX idx_holding_entity ON holding(entity_id, from_date);\n\n-- Customers, suppliers and anyone else money moves between. One table: the\n-- same shop sells to the business on Tuesday and buys from it on Friday, and\n-- two tables would make that two half-known parties.\nCREATE TABLE party (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  code          TEXT NOT NULL,\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  kind          TEXT NOT NULL DEFAULT 'both'\n                CHECK (kind IN ('customer','supplier','both','employee','authority')),\n  -- A Thai tax invoice names the buyer's registered address and TIN, and head\n  -- office vs branch is part of the address (00000 = head office).\n  tax_id        TEXT,\n  branch        TEXT DEFAULT '00000',\n  is_company    INTEGER NOT NULL DEFAULT 1,    -- decides PND53 vs PND3 on withholding\n  address_en    TEXT,\n  address_th    TEXT,\n  email         TEXT,\n  phone         TEXT,\n  country       TEXT NOT NULL DEFAULT 'TH',\n  currency      TEXT,                          -- billing currency when not the entity's\n  terms_days    INTEGER NOT NULL DEFAULT 0,\n  status        TEXT NOT NULL DEFAULT 'active'\n                CHECK (status IN ('active','archived')),\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  UNIQUE (entity_id, code)\n);\n\n-- Rates that change by decree and by year: VAT, withholding, social security,\n-- income tax bands. Dated rows rather than constants in code, because a\n-- payslip for March must keep being reproducible in December.\nCREATE TABLE rate (\n  id            TEXT PRIMARY KEY,\n  scope         TEXT NOT NULL,                 -- 'vat' | 'wht' | 'sso' | 'pit'\n  code          TEXT NOT NULL,                 -- 'standard' | 'service' | 'employee_pct' ...\n  value_bp      INTEGER,                       -- basis points for a percentage\n  value_satang  INTEGER,                       -- an amount cap or floor\n  from_date     TEXT NOT NULL,\n  to_date       TEXT,\n  source        TEXT,                          -- where the number came from\n  UNIQUE (scope, code, from_date)\n);\n\n-- Document and journal numbering. Per entity, per kind, per year.\nCREATE TABLE counter (\n  name          TEXT PRIMARY KEY,\n  value         INTEGER NOT NULL DEFAULT 0\n);\n\n-- Append-only record of who did what. Nothing in this system deletes; a\n-- mistake is reversed and both the error and the reversal stay readable.\nCREATE TABLE audit (\n  id            TEXT PRIMARY KEY,\n  at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  entity_id     TEXT,\n  person_id     TEXT,\n  action        TEXT NOT NULL,\n  object_kind   TEXT,\n  object_id     TEXT,\n  detail        TEXT\n);\nCREATE INDEX idx_audit_object ON audit(object_kind, object_id);\nCREATE INDEX idx_audit_at ON audit(at DESC);\n\nCREATE TABLE setting (\n  key           TEXT PRIMARY KEY,\n  value         TEXT NOT NULL\n);\n"],
  ["0002_books.sql", "-- 0002_books.sql — the ledger. Double entry, append-only, segmented by project.\n--\n-- WHY DOUBLE ENTRY for a one-person operation with partners: the moment two\n-- people share in a result, \"what did we make\" and \"what is mine\" are\n-- different questions, and a cashbook answers neither once stock, unpaid\n-- invoices and withheld tax exist. The second entry is also the only check\n-- that catches a typo the same day it is made.\n--\n-- WHAT IS NEVER EDITED: a posted journal. A correction is a new journal that\n-- reverses the old one and a right one after it. Editing history is how books\n-- stop matching the bank.\n\nCREATE TABLE account (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  code          TEXT NOT NULL,                 -- '1000', '4200'\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  type          TEXT NOT NULL\n                CHECK (type IN ('asset','liability','equity','income','expense')),\n  -- Sub-type drives the reports without a second lookup table: which lines are\n  -- cash, which liability is a tax the entity collected for someone else.\n  subtype       TEXT,                          -- 'cash','ar','ap','stock','vat_out','vat_in','wht_pay','wht_recv','sso','equity_partner','cogs'\n  currency      TEXT,                          -- NULL = the entity's currency\n  person_id     TEXT REFERENCES person(id),    -- partner capital / drawings accounts\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  note          TEXT,\n  UNIQUE (entity_id, code)\n);\nCREATE INDEX idx_account_type ON account(entity_id, type, subtype);\n\n-- An accounting period. Closing one refuses further postings into it, which is\n-- what makes a filed return stay true after it is filed.\nCREATE TABLE period (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  ym            TEXT NOT NULL,                 -- YYYY-MM\n  status        TEXT NOT NULL DEFAULT 'open'\n                CHECK (status IN ('open','closed')),\n  closed_at     TEXT,\n  closed_by     TEXT REFERENCES person(id),\n  UNIQUE (entity_id, ym)\n);\n\nCREATE TABLE journal (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id),\n  ref           TEXT NOT NULL,                 -- 'JV-2026-0042'\n  on_date       TEXT NOT NULL,                 -- YYYY-MM-DD, Bangkok local day\n  ym            TEXT NOT NULL,                 -- denormalised for period checks\n  memo_en       TEXT,\n  memo_th       TEXT,\n  -- Where this journal came from, so nothing in the ledger is orphaned:\n  -- an invoice, a payment, a payslip, a stock move, or a person typing.\n  source_kind   TEXT NOT NULL DEFAULT 'manual',\n  source_id     TEXT,\n  -- Two journals with the same key are the same event seen twice. A billing\n  -- run that half-finished and is run again must not double-bill.\n  idem_key      TEXT UNIQUE,\n  reverses_id   TEXT REFERENCES journal(id),\n  posted_by     TEXT REFERENCES person(id),\n  posted_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  UNIQUE (entity_id, ref)\n);\nCREATE INDEX idx_journal_date ON journal(entity_id, on_date);\nCREATE INDEX idx_journal_source ON journal(source_kind, source_id);\n\nCREATE TABLE journal_line (\n  id            TEXT PRIMARY KEY,\n  journal_id    TEXT NOT NULL REFERENCES journal(id) ON DELETE CASCADE,\n  seq           INTEGER NOT NULL,\n  account_id    TEXT NOT NULL REFERENCES account(id),\n  -- Signed minor units against the account. Positive = debit, negative =\n  -- credit. One signed column instead of two nullable ones: a journal balances\n  -- when its lines sum to zero, which is one SUM and no NULL arithmetic.\n  amount        INTEGER NOT NULL,\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  -- When the line is not in the entity's own currency, both the foreign amount\n  -- and the booked amount are kept. The books add up in one currency; the\n  -- invoice still says what the customer was asked to pay.\n  fx_amount     INTEGER,\n  fx_rate_ppm   INTEGER,                       -- parts per million, integer\n  project_id    TEXT REFERENCES project(id),\n  party_id      TEXT REFERENCES party(id),\n  person_id     TEXT REFERENCES person(id),\n  cost_centre   TEXT NOT NULL DEFAULT 'company'\n                CHECK (cost_centre IN ('company','household')),\n  tax_code      TEXT,                          -- 'VAT7','WHT3','WHT5','EXEMPT','ZERO'\n  memo          TEXT\n);\nCREATE INDEX idx_line_journal ON journal_line(journal_id, seq);\nCREATE INDEX idx_line_account ON journal_line(account_id);\nCREATE INDEX idx_line_project ON journal_line(project_id);\nCREATE INDEX idx_line_party ON journal_line(party_id);\n\n-- Trial balance by account, and the same figures by project. Views rather\n-- than a maintained balance column: nothing to fall out of step, and SQLite\n-- answers both from the indexes above at this size.\nCREATE VIEW v_account_balance AS\n  SELECT j.entity_id, l.account_id, a.code, a.name_en, a.name_th, a.type,\n         a.subtype, SUM(l.amount) AS balance\n    FROM journal_line l\n    JOIN journal j ON j.id = l.journal_id\n    JOIN account a ON a.id = l.account_id\n   GROUP BY j.entity_id, l.account_id;\n\nCREATE VIEW v_project_result AS\n  SELECT j.entity_id, l.project_id, a.type,\n         j.ym, SUM(l.amount) AS amount\n    FROM journal_line l\n    JOIN journal j ON j.id = l.journal_id\n    JOIN account a ON a.id = l.account_id\n   WHERE a.type IN ('income','expense')\n   GROUP BY j.entity_id, l.project_id, a.type, j.ym;\n"],
  ["0003_documents.sql", "-- 0003_documents.sql — the paper: quotations, invoices, tax invoices, receipts,\n-- supplier bills, credit notes, and the payments that settle them.\n--\n-- A Thai full tax invoice (Revenue Code s.86/4) carries: the words\n-- \"ใบกำกับภาษี\", the seller's name, address and TIN, the buyer's name, address\n-- and TIN, a serial number, the date of issue, the description and quantity,\n-- and the VAT shown as its own amount. Those are columns here rather than free\n-- text so a document cannot be issued half-formed.\n--\n-- WITHHOLDING RUNS THE OTHER WAY from most countries' invoicing: a Thai\n-- company paying for services withholds tax from the payment and hands the\n-- supplier a certificate. So an invoice for 100 is settled by a bank credit of\n-- 97 plus a piece of paper worth 3, and the 3 is an asset until it is used\n-- against the year's tax. `wht_bp` on the document says what the payer is\n-- expected to withhold; the payment records what they actually did.\n\nCREATE TABLE doc (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id),\n  kind          TEXT NOT NULL\n                CHECK (kind IN ('quote','invoice','tax_invoice','receipt',\n                                'bill','credit_note','debit_note')),\n  direction     TEXT NOT NULL CHECK (direction IN ('out','in')),\n  number        TEXT NOT NULL,\n  party_id      TEXT NOT NULL REFERENCES party(id),\n  project_id    TEXT REFERENCES project(id),\n\n  issue_date    TEXT NOT NULL,                 -- YYYY-MM-DD\n  due_date      TEXT,\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  fx_rate_ppm   INTEGER,                       -- to the entity currency, when different\n\n  -- Totals in the document's own currency, minor units.\n  net           INTEGER NOT NULL DEFAULT 0,\n  vat           INTEGER NOT NULL DEFAULT 0,\n  gross         INTEGER NOT NULL DEFAULT 0,\n  wht_bp        INTEGER NOT NULL DEFAULT 0,    -- expected withholding, basis points\n  wht           INTEGER NOT NULL DEFAULT 0,\n  expect_paid   INTEGER NOT NULL DEFAULT 0,    -- gross - wht: what should land in the bank\n\n  paid          INTEGER NOT NULL DEFAULT 0,    -- settled so far, cash\n  wht_credited  INTEGER NOT NULL DEFAULT 0,    -- settled so far, by certificate\n\n  status        TEXT NOT NULL DEFAULT 'draft'\n                CHECK (status IN ('draft','issued','part_paid','paid','void')),\n  -- A document is issued once. Editing an issued document is not possible;\n  -- it is voided by a credit note and re-issued, which is what the number\n  -- sequence has to show a tax officer.\n  issued_at     TEXT,\n  voided_by     TEXT REFERENCES doc(id),\n  journal_id    TEXT REFERENCES journal(id),\n\n  subject_en    TEXT,\n  subject_th    TEXT,\n  note_en       TEXT,\n  note_th       TEXT,\n  ref_external  TEXT,                          -- their PO, their invoice number\n  idem_key      TEXT UNIQUE,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  UNIQUE (entity_id, kind, number)\n);\nCREATE INDEX idx_doc_party ON doc(party_id, status);\nCREATE INDEX idx_doc_open ON doc(entity_id, direction, status, due_date);\nCREATE INDEX idx_doc_period ON doc(entity_id, issue_date);\n\nCREATE TABLE doc_line (\n  id            TEXT PRIMARY KEY,\n  doc_id        TEXT NOT NULL REFERENCES doc(id) ON DELETE CASCADE,\n  seq           INTEGER NOT NULL,\n  desc_en       TEXT NOT NULL,\n  desc_th       TEXT,\n  qty_milli     INTEGER NOT NULL DEFAULT 1000, -- thousandths, so 0.5 days is exact\n  unit          TEXT,                          -- 'item','hour','day','month','seat'\n  unit_price    INTEGER NOT NULL DEFAULT 0,    -- minor units\n  discount      INTEGER NOT NULL DEFAULT 0,\n  tax_code      TEXT NOT NULL DEFAULT 'NONE',  -- 'VAT7','EXEMPT','ZERO','NONE'\n  account_id    TEXT REFERENCES account(id),   -- revenue or expense account\n  project_id    TEXT REFERENCES project(id),\n  item_id       TEXT,                          -- stock piece, wired in 0004\n  net           INTEGER NOT NULL DEFAULT 0,\n  vat           INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX idx_docline_doc ON doc_line(doc_id, seq);\n\n-- Money that actually moved, and the certificate that came with it.\nCREATE TABLE payment (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id),\n  direction     TEXT NOT NULL CHECK (direction IN ('in','out')),\n  on_date       TEXT NOT NULL,\n  party_id      TEXT REFERENCES party(id),\n  account_id    TEXT NOT NULL REFERENCES account(id),   -- the bank or cash account\n  method        TEXT NOT NULL DEFAULT 'transfer'\n                CHECK (method IN ('transfer','promptpay','cash','card','offset','other')),\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  amount        INTEGER NOT NULL,              -- what landed, minor units\n  wht_amount    INTEGER NOT NULL DEFAULT 0,    -- withheld by the payer\n  fee           INTEGER NOT NULL DEFAULT 0,    -- bank charge taken from the transfer\n  slip_ref      TEXT,                          -- transaction reference from the slip QR\n  wht_cert_no   TEXT,\n  journal_id    TEXT REFERENCES journal(id),\n  idem_key      TEXT UNIQUE,\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\nCREATE INDEX idx_payment_party ON payment(party_id, on_date);\n\n-- One payment can settle several documents and one document can take several\n-- payments, so the link is its own table and the document totals are derived\n-- from it rather than typed.\nCREATE TABLE allocation (\n  id            TEXT PRIMARY KEY,\n  payment_id    TEXT NOT NULL REFERENCES payment(id) ON DELETE CASCADE,\n  doc_id        TEXT NOT NULL REFERENCES doc(id) ON DELETE CASCADE,\n  amount        INTEGER NOT NULL,              -- cash portion\n  wht_amount    INTEGER NOT NULL DEFAULT 0,    -- certificate portion\n  UNIQUE (payment_id, doc_id)\n);\n"],
  ["0004_stock.sql", "-- 0004_stock.sql — pieces, not quantities.\n--\n-- An amulet is not a SKU with a count: each piece has its own wat, series,\n-- condition, price and photograph, and two that look identical are not\n-- interchangeable to a buyer. So stock is one row per PIECE, and a \"quantity\"\n-- is the number of rows matching a filter. This is slower per row and correct\n-- per object; at the volume one person can photograph, correctness wins.\n--\n-- Cost is what was paid for the piece plus what it cost to get it ready, and\n-- margin is only true once both are on the row. A piece bought in a bundle\n-- carries its share of the bundle price, apportioned at intake — recorded as\n-- an apportionment so the arithmetic can be re-read later.\n\nCREATE TABLE item (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id),\n  project_id    TEXT REFERENCES project(id),\n  sku           TEXT NOT NULL,\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  category      TEXT,                          -- 'amulet','takrut','phaa yant','book'\n  tradition     TEXT,                          -- wat / lineage / maker, as recorded\n  series        TEXT,\n  year_be       INTEGER,                       -- Buddhist era year, as marked on the piece\n  condition     TEXT,\n  -- Cost side. Acquisition is what was paid; prep is cleaning, casing, a new\n  -- cord, postage in. Both sit in the stock account until the piece sells.\n  acq_cost      INTEGER NOT NULL DEFAULT 0,\n  prep_cost     INTEGER NOT NULL DEFAULT 0,\n  acq_doc_id    TEXT REFERENCES doc(id),\n  acq_date      TEXT,\n  acq_lot       TEXT,                          -- bundle this came in with\n  -- Sale side.\n  ask_price     INTEGER,\n  sold_price    INTEGER,\n  sold_doc_id   TEXT REFERENCES doc(id),\n  sold_date     TEXT,\n  status        TEXT NOT NULL DEFAULT 'in_stock'\n                CHECK (status IN ('in_stock','listed','reserved','sold','returned','gifted','written_off')),\n  location      TEXT,                          -- 'trunk 2','safe','with Beer'\n  listing_url   TEXT,\n  photo_count   INTEGER NOT NULL DEFAULT 0,\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  UNIQUE (entity_id, sku)\n);\nCREATE INDEX idx_item_status ON item(entity_id, status);\nCREATE INDEX idx_item_project ON item(project_id, status);\nCREATE INDEX idx_item_lot ON item(acq_lot);\n\n-- Every change of hands or of state, kept as its own row. The current status\n-- on `item` is a convenience; this table is what it is derived from, and the\n-- only place that can answer \"where was it in March\".\nCREATE TABLE item_move (\n  id            TEXT PRIMARY KEY,\n  item_id       TEXT NOT NULL REFERENCES item(id) ON DELETE CASCADE,\n  at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  on_date       TEXT NOT NULL,\n  kind          TEXT NOT NULL\n                CHECK (kind IN ('acquire','prep','list','reserve','unlist','sell',\n                                'return','gift','write_off','move','reprice')),\n  from_status   TEXT,\n  to_status     TEXT,\n  amount        INTEGER,                       -- cost or price attached to the move\n  location      TEXT,\n  person_id     TEXT REFERENCES person(id),\n  doc_id        TEXT REFERENCES doc(id),\n  journal_id    TEXT REFERENCES journal(id),\n  note          TEXT\n);\nCREATE INDEX idx_move_item ON item_move(item_id, at);\n\n-- How a bundle price was split across the pieces it contained. Kept because\n-- \"why does this piece cost ฿412\" is a question that gets asked a year later.\nCREATE TABLE lot_split (\n  id            TEXT PRIMARY KEY,\n  acq_lot       TEXT NOT NULL,\n  item_id       TEXT NOT NULL REFERENCES item(id) ON DELETE CASCADE,\n  basis         TEXT NOT NULL DEFAULT 'even'\n                CHECK (basis IN ('even','by_ask','by_weight','manual')),\n  weight_milli  INTEGER,\n  amount        INTEGER NOT NULL,\n  UNIQUE (acq_lot, item_id)\n);\n"],
  ["0005_subscriptions.sql", "-- 0005_subscriptions.sql — recurring revenue: seats, retainers, memberships.\n--\n-- The shape that matters is not the price, it is the PERIOD: a subscription\n-- bills for a span of dates, and billing it twice for the same span is the\n-- failure this table is built to refuse. `billed_period` holds one row per\n-- (subscription, period) and the unique index is what makes a re-run of a\n-- half-finished billing run harmless.\n--\n-- Trials and free tiers are a price of zero, not a separate kind — a free seat\n-- still has a start, an end and a person to talk to, and it becomes paid by a\n-- price change rather than a migration.\n\nCREATE TABLE plan (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id),\n  project_id    TEXT REFERENCES project(id),\n  code          TEXT NOT NULL,\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  price         INTEGER NOT NULL DEFAULT 0,    -- minor units, per interval, per seat\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  interval      TEXT NOT NULL DEFAULT 'month'\n                CHECK (interval IN ('month','quarter','year','once')),\n  tax_code      TEXT NOT NULL DEFAULT 'NONE',\n  account_id    TEXT REFERENCES account(id),   -- revenue account\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  note          TEXT,\n  UNIQUE (entity_id, code)\n);\n\nCREATE TABLE subscription (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id),\n  party_id      TEXT NOT NULL REFERENCES party(id),\n  plan_id       TEXT NOT NULL REFERENCES plan(id),\n  seats         INTEGER NOT NULL DEFAULT 1,\n  price_override INTEGER,                      -- a negotiated price, per seat\n  currency      TEXT,\n  start_date    TEXT NOT NULL,\n  end_date      TEXT,                          -- NULL = open ended\n  next_bill_on  TEXT,                          -- YYYY-MM-DD, the first day of the next span\n  anchor_day    INTEGER,                       -- day of month to bill on; clamps to month end\n  status        TEXT NOT NULL DEFAULT 'active'\n                CHECK (status IN ('active','paused','cancelled','ended')),\n  cancel_at_end INTEGER NOT NULL DEFAULT 0,\n  po_ref        TEXT,\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\nCREATE INDEX idx_sub_due ON subscription(entity_id, status, next_bill_on);\nCREATE INDEX idx_sub_party ON subscription(party_id, status);\n\nCREATE TABLE billed_period (\n  id            TEXT PRIMARY KEY,\n  subscription_id TEXT NOT NULL REFERENCES subscription(id) ON DELETE CASCADE,\n  from_date     TEXT NOT NULL,\n  to_date       TEXT NOT NULL,\n  doc_id        TEXT REFERENCES doc(id),\n  seats         INTEGER NOT NULL DEFAULT 1,\n  amount        INTEGER NOT NULL DEFAULT 0,\n  billed_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  UNIQUE (subscription_id, from_date)\n);\n"],
  ["0006_payroll.sql", "-- 0006_payroll.sql — employment, payslips, and the three deductions.\n--\n-- One employment row per person per entity, holding the pay unit rather than a\n-- monthly figure only: a salaried month and a ฿600 half day are the same table\n-- with a different `pay_unit`, which is how the tasking board already counts\n-- work blocks.\n--\n-- A payslip is computed once and then FROZEN — gross, each deduction, the rate\n-- each deduction was computed at, and the net. Recomputing an old payslip from\n-- today's rate table would silently rewrite what somebody was paid, so the\n-- numbers used are stored on the slip beside the result.\n--\n-- Three deductions, three different authorities:\n--   • social security   — employee share, matched by the employer\n--   • withheld income tax — the employer's estimate of the year's tax, in\n--     twelfths, paid to the Revenue Department monthly\n--   • provident fund / other — optional, not assumed\n-- The arithmetic in `lib/thai_tax.mjs` follows the rate rows; the rows carry\n-- their source. Figures for a filing are worth a bookkeeper's eye before they\n-- are filed.\n\nCREATE TABLE employment (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id),\n  person_id     TEXT NOT NULL REFERENCES person(id),\n  title_en      TEXT,\n  title_th      TEXT,\n  pay_unit      TEXT NOT NULL DEFAULT 'month'\n                CHECK (pay_unit IN ('month','day','half_day','hour','block')),\n  pay_rate      INTEGER NOT NULL,              -- minor units per pay_unit\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  hours_per_day INTEGER NOT NULL DEFAULT 8,\n  start_date    TEXT NOT NULL,\n  end_date      TEXT,\n  sso_registered INTEGER NOT NULL DEFAULT 0,\n  sso_from      TEXT,\n  tax_withheld  INTEGER NOT NULL DEFAULT 0,    -- does the employer withhold PIT\n  -- Allowances the person has declared, in baht per year. Used only to\n  -- estimate withholding; the year-end return is theirs, not the employer's.\n  allowances    TEXT,                          -- JSON: {\"spouse\":60000,\"children\":2}\n  cost_centre   TEXT NOT NULL DEFAULT 'company'\n                CHECK (cost_centre IN ('company','household')),\n  contract_ref  TEXT,\n  note          TEXT,\n  UNIQUE (entity_id, person_id, start_date)\n);\n\nCREATE TABLE pay_run (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id),\n  ym            TEXT NOT NULL,                 -- YYYY-MM\n  pay_date      TEXT NOT NULL,\n  status        TEXT NOT NULL DEFAULT 'draft'\n                CHECK (status IN ('draft','approved','paid','void')),\n  journal_id    TEXT REFERENCES journal(id),\n  approved_by   TEXT REFERENCES person(id),\n  approved_at   TEXT,\n  note          TEXT,\n  UNIQUE (entity_id, ym)\n);\n\nCREATE TABLE payslip (\n  id            TEXT PRIMARY KEY,\n  pay_run_id    TEXT NOT NULL REFERENCES pay_run(id) ON DELETE CASCADE,\n  employment_id TEXT NOT NULL REFERENCES employment(id),\n  person_id     TEXT NOT NULL REFERENCES person(id),\n  units_milli   INTEGER NOT NULL DEFAULT 1000, -- days/blocks worked, thousandths\n  gross         INTEGER NOT NULL DEFAULT 0,\n  sso_employee  INTEGER NOT NULL DEFAULT 0,\n  sso_employer  INTEGER NOT NULL DEFAULT 0,\n  wht           INTEGER NOT NULL DEFAULT 0,\n  other_deduct  INTEGER NOT NULL DEFAULT 0,\n  net           INTEGER NOT NULL DEFAULT 0,\n  -- The rates this slip was computed at, frozen on the row.\n  sso_rate_bp   INTEGER,\n  sso_cap       INTEGER,\n  wht_basis     TEXT,                          -- JSON: the annualised working\n  paid_at       TEXT,\n  payment_id    TEXT REFERENCES payment(id),\n  UNIQUE (pay_run_id, employment_id)\n);\nCREATE INDEX idx_payslip_person ON payslip(person_id);\n\nCREATE TABLE payslip_line (\n  id            TEXT PRIMARY KEY,\n  payslip_id    TEXT NOT NULL REFERENCES payslip(id) ON DELETE CASCADE,\n  seq           INTEGER NOT NULL,\n  kind          TEXT NOT NULL CHECK (kind IN ('earning','deduction','employer_cost','note')),\n  code          TEXT NOT NULL,\n  desc_en       TEXT NOT NULL,\n  desc_th       TEXT,\n  amount        INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX idx_payslipline ON payslip_line(payslip_id, seq);\n"],
  ["0007_compliance.sql", "-- 0007_compliance.sql — what is owed to an office, and by when.\n--\n-- An obligation is a RULE (this entity, this filing, monthly, due on the 7th);\n-- a filing is one occurrence of it. Generating occurrences from rules means a\n-- new entity inherits the calendar instead of someone remembering to type it,\n-- and a rule that stops applying — deregistration, a closed year — stops\n-- generating without touching the filings already made.\n--\n-- Due dates are DATES, and a date whose arithmetic is not written down is a\n-- guess. `due_rule` holds the arithmetic: 'day:7' is the seventh of the month\n-- after the period; 'day:15' the fifteenth; 'days:150' a hundred and fifty\n-- days after the year end. `efile_bonus_days` holds the extension electronic\n-- filing carries, which is a different date and worth showing beside it.\n\nCREATE TABLE obligation (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  code          TEXT NOT NULL,                 -- 'PND1','PND3','PND53','PP30','SSO','PND50','PND51','DBD'\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  authority     TEXT NOT NULL,                 -- 'revenue','sso','dbd'\n  frequency     TEXT NOT NULL\n                CHECK (frequency IN ('monthly','quarterly','half_year','annual','once')),\n  due_rule      TEXT NOT NULL,                 -- 'day:7' | 'day:15' | 'days:150' | 'months:4'\n  efile_bonus_days INTEGER NOT NULL DEFAULT 0,\n  applies_when  TEXT,                          -- 'vat_registered' | 'has_employees' | 'always'\n  active_from   TEXT NOT NULL,\n  active_to     TEXT,\n  source        TEXT,\n  note          TEXT,\n  UNIQUE (entity_id, code, active_from)\n);\n\nCREATE TABLE filing (\n  id            TEXT PRIMARY KEY,\n  obligation_id TEXT NOT NULL REFERENCES obligation(id) ON DELETE CASCADE,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  period        TEXT NOT NULL,                 -- YYYY-MM | YYYY-Q1 | YYYY\n  due_date      TEXT NOT NULL,\n  efile_date    TEXT,\n  amount        INTEGER,                       -- what it came to, once known\n  status        TEXT NOT NULL DEFAULT 'due'\n                CHECK (status IN ('due','prepared','filed','paid','waived','late')),\n  filed_on      TEXT,\n  ref           TEXT,                          -- receipt number from the office\n  person_id     TEXT REFERENCES person(id),    -- who filed it\n  note          TEXT,\n  UNIQUE (obligation_id, period)\n);\nCREATE INDEX idx_filing_due ON filing(entity_id, status, due_date);\n"],
  ["0008_intake.sql", "-- 0008_intake.sql — how things get in without anybody being trained.\n--\n-- The bookkeeper's real problem is not posting; it is that the receipts live in\n-- other people's pockets. So the ways IN are first-class: a link the client can\n-- open on their phone, an address they can forward to, a chat they already use,\n-- the QR on a bank transfer slip. Each arrival lands here as an ITEM — not yet\n-- a bill, not yet in the ledger, and never posted by guesswork.\n--\n-- An item carries what was sent plus what the system GUESSED (which supplier,\n-- which account), and both stay on the row: the guess is visible next to the\n-- evidence, and one tap turns it into a draft the bookkeeper can change.\n-- Nothing an item says reaches the books until a person says so.\n\nCREATE TABLE intake_channel (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  kind          TEXT NOT NULL CHECK (kind IN ('link','email','line','slip')),\n  -- The link token, the forwarding address, the chat id. For a link this is\n  -- the only secret there is, so it is long and it can be replaced.\n  address       TEXT NOT NULL,\n  label         TEXT,\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  UNIQUE (entity_id, kind, address)\n);\nCREATE INDEX idx_channel_entity ON intake_channel(entity_id, is_active);\n\nCREATE TABLE inbox_item (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  channel_id    TEXT REFERENCES intake_channel(id) ON DELETE SET NULL,\n  source        TEXT NOT NULL DEFAULT 'link'\n                CHECK (source IN ('link','email','line','slip','manual')),\n  received_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  on_date       TEXT,                       -- the date on the receipt, when there is one\n  from_ref      TEXT,                       -- who sent it, as they identified themselves\n\n  kind          TEXT NOT NULL DEFAULT 'unknown'\n                CHECK (kind IN ('bill','invoice','payment','unknown')),\n  description   TEXT,\n  amount        INTEGER,\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  vat           INTEGER,\n  tax_id        TEXT,                       -- read off the receipt, if it carries one\n  slip_ref      TEXT,\n\n  -- The guesses, kept apart from what was sent.\n  party_id      TEXT REFERENCES party(id),\n  party_hint    TEXT,\n  account_hint  TEXT,\n  confidence    INTEGER NOT NULL DEFAULT 0, -- 0-100, why the guess is offered at all\n\n  photo_name    TEXT,\n  photo_data    TEXT,                       -- data URL; the photo IS the record\n\n  status        TEXT NOT NULL DEFAULT 'new'\n                CHECK (status IN ('new','used','dismissed')),\n  doc_id        TEXT REFERENCES doc(id) ON DELETE SET NULL,\n  payment_id    TEXT REFERENCES payment(id) ON DELETE SET NULL,\n  dismissed_why TEXT,\n  note          TEXT,\n  idem_key      TEXT UNIQUE\n);\nCREATE INDEX idx_inbox_entity ON inbox_item(entity_id, status, received_at DESC);\n"],
  ["0009_referrals.sql", "-- 0009_referrals.sql — work sent to somebody else, and the share of it that\n-- comes back.\n--\n-- A referral is not an invoice and not a sale. It is a case that left here,\n-- and it earns nothing until the other side takes it on and finishes it. So it\n-- has a life of its own — sent, accepted or declined, completed, billed, paid —\n-- and only the step from completed to billed touches the ledger.\n--\n-- THE AGREEMENT IS A DATED ROW, like every other number that somebody else can\n-- change: a percentage of the fee, a fixed amount per case, or a ladder that\n-- pays more above a volume. Changing it closes the old row rather than\n-- rewriting what was already earned under it.\n--\n-- WHAT IS DELIBERATELY NOT HERE: the client's contact details. A commission\n-- needs a reference, a service and a fee. Names and phone numbers belong to the\n-- desk that took the case, and copying them into a second system to justify an\n-- invoice is a liability with no upside.\n\nCREATE TABLE referral_agreement (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  -- Who pays: the party this entity invoices for the commission.\n  party_id      TEXT NOT NULL REFERENCES party(id),\n  code          TEXT NOT NULL,              -- the origin/partner code on the enquiry\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  basis         TEXT NOT NULL DEFAULT 'percent_of_fee'\n                CHECK (basis IN ('percent_of_fee','fixed_per_case','tiered')),\n  rate_bp       INTEGER,                    -- percent basis: basis points of the case fee\n  fixed_amount  INTEGER,                    -- fixed basis: minor units per completed case\n  tiers         TEXT,                       -- tiered: JSON [{from_cases, rate_bp}]\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  -- What the payer does with tax. A Thai company paying a service fee withholds;\n  -- whether this entity charges VAT follows its own registration.\n  wht_bp        INTEGER NOT NULL DEFAULT 300,\n  project_id    TEXT REFERENCES project(id),\n  account_code  TEXT NOT NULL DEFAULT '4900',\n  terms_days    INTEGER NOT NULL DEFAULT 15,\n  from_date     TEXT NOT NULL,\n  to_date       TEXT,\n  source        TEXT,                       -- where the terms are written down\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\nCREATE INDEX idx_agreement_live ON referral_agreement(entity_id, code, from_date);\n\nCREATE TABLE referral (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  agreement_id  TEXT REFERENCES referral_agreement(id),\n  -- The id the other system already uses. Imports match on it, so the same\n  -- enquiry imported twice is one referral.\n  external_id   TEXT,\n  code          TEXT,                       -- origin or partner code as captured\n  sent_on       TEXT NOT NULL,\n  label         TEXT,                       -- 'Retirement extension', not a person\n  service       TEXT,\n  channel       TEXT,                       -- 'site','line','in person','email'\n\n  status        TEXT NOT NULL DEFAULT 'sent'\n                CHECK (status IN ('sent','accepted','declined','completed','billed','paid','void')),\n  accepted_on   TEXT,\n  completed_on  TEXT,\n  declined_why  TEXT,\n\n  case_fee      INTEGER,                    -- what the other side charged, when known\n  commission    INTEGER,                    -- worked out at completion, then frozen\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  -- The agreement as it stood when this case completed, kept on the row so a\n  -- later change of terms cannot rewrite what was earned.\n  basis_used    TEXT,\n  rate_used_bp  INTEGER,\n\n  doc_id        TEXT REFERENCES doc(id) ON DELETE SET NULL,\n  billed_period TEXT,                       -- YYYY-MM\n  note          TEXT,\n  idem_key      TEXT UNIQUE,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\nCREATE INDEX idx_referral_status ON referral(entity_id, status, sent_on);\nCREATE INDEX idx_referral_external ON referral(external_id);\nCREATE UNIQUE INDEX idx_referral_billed ON referral(agreement_id, billed_period, id);\n"],
  ["0010_paying.sql", "-- 0010_paying.sql — the ways money can actually move, and the small tricks that\n-- take the typing out of it.\n--\n-- THREE BARRIERS THIS REMOVES:\n--\n--   1. Typing. A PromptPay QR carries the payee AND the exact amount, so the\n--      payer scans and confirms. No account number read off a screen.\n--   2. Working out which invoice a bank credit belongs to. Two customers owing\n--      ฿2,000 produce two identical credits. A unique satang tail — ฿2,000.37\n--      and ฿2,000.38 — makes the amount itself the reference. The stray satang\n--      is shown on the document as its own line rather than hidden.\n--   3. Signing in. A payment link carries its own token: the payer opens it,\n--      sees what is owed, scans, and can say they have paid.\n\nCREATE TABLE pay_method (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  kind          TEXT NOT NULL\n                CHECK (kind IN ('promptpay','bank','cash','link','other')),\n  label_en      TEXT NOT NULL,\n  label_th      TEXT,\n  -- PromptPay: the mobile number, tax id or e-wallet id that receives.\n  payee_id      TEXT,\n  -- Bank transfer: what a payer needs to fill a transfer form.\n  bank_name     TEXT,\n  account_name  TEXT,\n  account_no    TEXT,\n  -- A card or foreign-payment page, with {amount} and {ref} substituted.\n  link_template TEXT,\n  -- Where the money lands in the books.\n  account_code  TEXT NOT NULL DEFAULT '1010',\n  direction     TEXT NOT NULL DEFAULT 'in' CHECK (direction IN ('in','out','both')),\n  is_default    INTEGER NOT NULL DEFAULT 0,\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  sort          INTEGER NOT NULL DEFAULT 0,\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\nCREATE INDEX idx_paymethod_entity ON pay_method(entity_id, direction, is_active);\n\n-- How to pay THEM: kept on the party, because paying a supplier by scanning is\n-- the same trick in the other direction.\nALTER TABLE party ADD COLUMN pay_promptpay TEXT;\nALTER TABLE party ADD COLUMN pay_bank TEXT;\nALTER TABLE party ADD COLUMN pay_account_no TEXT;\nALTER TABLE party ADD COLUMN pay_account_name TEXT;\n\n-- The tail and the link live on the document.\nALTER TABLE doc ADD COLUMN pay_tail INTEGER NOT NULL DEFAULT 0;   -- 0-99 satang\nALTER TABLE doc ADD COLUMN pay_token TEXT;\nCREATE UNIQUE INDEX idx_doc_paytoken ON doc(pay_token);\n\n-- What a payer said they did, before the bank confirms it. A claim is not a\n-- payment: it sits beside the invoice until the credit appears, which is what\n-- stops a screenshot from closing an invoice.\nCREATE TABLE pay_claim (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  doc_id        TEXT REFERENCES doc(id) ON DELETE CASCADE,\n  claimed_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  amount        INTEGER,\n  method        TEXT,\n  slip_ref      TEXT,\n  slip_raw      TEXT,             -- the slip's own QR text, when it was scanned\n  photo_name    TEXT,\n  note          TEXT,\n  status        TEXT NOT NULL DEFAULT 'new'\n                CHECK (status IN ('new','matched','rejected')),\n  payment_id    TEXT REFERENCES payment(id) ON DELETE SET NULL,\n  idem_key      TEXT UNIQUE\n);\nCREATE INDEX idx_claim_doc ON pay_claim(doc_id, status);\n"],
  ["0011_calendar.sql", "-- 0011_calendar.sql — days that are not working days, and where the books are.\n--\n-- A deadline that lands on a public holiday moves, an errand cannot be run when\n-- the office is shut, and a supplier in the south will not answer over Eid. So\n-- the calendar is part of the books rather than something kept beside them.\n--\n-- HOLIDAYS ARE ROWS, not a table compiled into the code. Thailand's fixed-date\n-- holidays are seeded; the Buddhist ones move with the lunar month and the\n-- cabinet announces substitute days each year, so those are added as they are\n-- announced rather than guessed at here. `moves_deadline` says whether a filing\n-- due that day slides to the next working day.\n\nCREATE TABLE holiday (\n  id            TEXT PRIMARY KEY,\n  -- NULL means every set of books in this database: a national holiday is not\n  -- a property of one company.\n  entity_id     TEXT REFERENCES entity(id) ON DELETE CASCADE,\n  on_date       TEXT NOT NULL,\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  kind          TEXT NOT NULL DEFAULT 'public'\n                CHECK (kind IN ('public','bank','observance','custom')),\n  moves_deadline INTEGER NOT NULL DEFAULT 1,\n  -- An observance whose date is calculated rather than observed says so.\n  expected      INTEGER NOT NULL DEFAULT 0,\n  source        TEXT,\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  note          TEXT,\n  UNIQUE (entity_id, on_date, name_en)\n);\nCREATE INDEX idx_holiday_date ON holiday(on_date, is_active);\n\n-- Where a set of books physically is: the day's length and the hours that hang\n-- off it are local facts.\nALTER TABLE entity ADD COLUMN place TEXT;\nALTER TABLE entity ADD COLUMN lat REAL;\nALTER TABLE entity ADD COLUMN lng REAL;\n"],
  ["0012_khmer.sql", "-- 0011_khmer.sql — a third language, and books kept under a second set of laws.\n--\n-- TWO CHANGES, both small, both load-bearing.\n--\n--   1. A `_km` column beside every `_en`/`_th` one. A row that a person reads —\n--      an account name, an invoice line, a filing — now carries Khmer as well.\n--      The reader picks their language and falls back rather than seeing a key.\n--   2. A jurisdiction on every rate. VAT is 7% in Thailand and 10% in Cambodia;\n--      both sets of books can sit in the same file, so a rate has to say which\n--      country's law it comes from. Existing rows are Thailand's, which is what\n--      they were.\n\nALTER TABLE entity ADD COLUMN name_km TEXT;\nALTER TABLE entity ADD COLUMN address_km TEXT;\nALTER TABLE project ADD COLUMN name_km TEXT;\nALTER TABLE person ADD COLUMN name_km TEXT;\nALTER TABLE party ADD COLUMN name_km TEXT;\nALTER TABLE party ADD COLUMN address_km TEXT;\nALTER TABLE account ADD COLUMN name_km TEXT;\nALTER TABLE journal ADD COLUMN memo_km TEXT;\nALTER TABLE doc ADD COLUMN subject_km TEXT;\nALTER TABLE doc ADD COLUMN note_km TEXT;\nALTER TABLE doc_line ADD COLUMN desc_km TEXT;\nALTER TABLE item ADD COLUMN name_km TEXT;\nALTER TABLE plan ADD COLUMN name_km TEXT;\nALTER TABLE employment ADD COLUMN title_km TEXT;\nALTER TABLE payslip_line ADD COLUMN desc_km TEXT;\nALTER TABLE obligation ADD COLUMN name_km TEXT;\nALTER TABLE referral_agreement ADD COLUMN name_km TEXT;\nALTER TABLE pay_method ADD COLUMN label_km TEXT;\nALTER TABLE holiday ADD COLUMN name_km TEXT;\n\nALTER TABLE rate ADD COLUMN jur TEXT NOT NULL DEFAULT 'TH';\nCREATE INDEX IF NOT EXISTS idx_rate_jur ON rate(jur, scope, code, from_date);\n\n-- The document wording an entity issues under: which country's invoice rules\n-- apply, and which language leads on the paper it hands over.\nALTER TABLE entity ADD COLUMN locale TEXT NOT NULL DEFAULT 'en';\nALTER TABLE entity ADD COLUMN second_locale TEXT;\n"],
  ["0012_line.sql", "-- 0012_line.sql — the chat app the work actually happens in.\n--\n-- In Thailand a client sends the receipt on LINE, asks what they owe on LINE,\n-- and says they have paid on LINE. Refusing that and asking them to open a\n-- portal loses the receipt, not the argument. So LINE is a way in and a way\n-- out, with the same rule as every other channel: what arrives becomes an item\n-- to look at, never a posting.\n--\n-- A CHAT ID CANNOT BE TYPED. LINE hands a user or group id over inside a signed\n-- webhook event and nowhere else, so this registry is written by the webhook\n-- and by no form. That is also what stops a stranger's message being filed into\n-- somebody's books.\n\nCREATE TABLE chat (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT REFERENCES entity(id) ON DELETE SET NULL,\n  channel_id    TEXT REFERENCES intake_channel(id) ON DELETE SET NULL,\n  kind          TEXT NOT NULL CHECK (kind IN ('user','group','room')),\n  chat_id       TEXT NOT NULL UNIQUE,      -- as LINE gave it\n  display_name  TEXT,\n  party_id      TEXT REFERENCES party(id) ON DELETE SET NULL,\n  person_id     TEXT REFERENCES person(id) ON DELETE SET NULL,\n  -- What this chat is allowed to be told. A group chat is not a private line:\n  -- money is off unless it is turned on, and a private queue is refused in code\n  -- whatever a row says.\n  may_see_money INTEGER NOT NULL DEFAULT 0,\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  joined_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  last_seen_at  TEXT\n);\nCREATE INDEX idx_chat_entity ON chat(entity_id, is_active);\n\n-- Messages waiting to go out. A row, not a call: the send can fail, be retried,\n-- or never be configured, and the books should not care.\nCREATE TABLE outbox (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT REFERENCES entity(id) ON DELETE CASCADE,\n  chat_id       TEXT,                      -- LINE user/group id\n  kind          TEXT NOT NULL DEFAULT 'push'\n                CHECK (kind IN ('push','reply','broadcast')),\n  reply_token   TEXT,\n  body          TEXT NOT NULL,\n  about_kind    TEXT,                      -- 'doc','filing','digest','claim'\n  about_id      TEXT,\n  status        TEXT NOT NULL DEFAULT 'queued'\n                CHECK (status IN ('queued','sent','failed','skipped')),\n  queued_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  sent_at       TEXT,\n  error         TEXT,\n  idem_key      TEXT UNIQUE\n);\nCREATE INDEX idx_outbox_status ON outbox(status, queued_at);\n"],
  ["0013_person_language.sql", "-- 0013_person_language.sql — a person's language is data, not an enum.\n--\n-- `person.locale` was written as CHECK (locale IN ('en','th')) when there were\n-- two languages. A third one cannot be added to a CHECK constraint in SQLite\n-- without rebuilding the table, and a fourth would mean doing it again, so the\n-- constraint goes: which languages exist is the business of the i18n packs,\n-- which already fall back to English for anything they do not have.\n--\n-- The rebuild follows the documented recipe — copy into a new table, drop the\n-- old one, rename — with foreign keys off for the duration so the rows that\n-- point at a person survive it.\n\nPRAGMA foreign_keys = OFF;\n\nCREATE TABLE person_new (\n  id            TEXT PRIMARY KEY,\n  code          TEXT NOT NULL UNIQUE,\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  name_km       TEXT,\n  locale        TEXT NOT NULL DEFAULT 'en',\n  email         TEXT,\n  line_user_id  TEXT,\n  tax_id        TEXT,\n  sso_number    TEXT,\n  status        TEXT NOT NULL DEFAULT 'active'\n                CHECK (status IN ('active','inactive')),\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\n\nINSERT INTO person_new (id, code, name_en, name_th, name_km, locale, email,\n  line_user_id, tax_id, sso_number, status, created_at)\nSELECT id, code, name_en, name_th, name_km, locale, email,\n  line_user_id, tax_id, sso_number, status, created_at FROM person;\n\nDROP TABLE person;\nALTER TABLE person_new RENAME TO person;\n\nPRAGMA foreign_keys = ON;\n"],
  ["0013_rate_card.sql", "-- 0013_rate_card.sql — the price they charge you, and the price you quote.\n--\n-- The arrangement that actually gets used between desks is not a percentage.\n-- One side does the work at a NET price; the other side quotes a retail price\n-- and keeps the difference. A retirement extension done at ฿16,000 and quoted\n-- at ฿25,000 is ฿9,000 to whoever brought the file, and no rate was involved.\n--\n-- So a service carries two prices and the margin is arithmetic between them.\n-- Both are dated rows: a net price rises when the other desk raises it, and\n-- what was earned under the old one keeps its own figures.\n\nCREATE TABLE service_rate (\n  id            TEXT PRIMARY KEY,\n  agreement_id  TEXT NOT NULL REFERENCES referral_agreement(id) ON DELETE CASCADE,\n  code          TEXT NOT NULL,              -- 'retirement-extension'\n  name_en       TEXT NOT NULL,\n  name_th       TEXT,\n  -- What the other desk charges for doing it.\n  net_price     INTEGER NOT NULL,\n  -- What the client is quoted. Null means \"no standard quote\": the case\n  -- carries its own, which is how one-off work behaves.\n  retail_price  INTEGER,\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  from_date     TEXT NOT NULL,\n  to_date       TEXT,\n  source        TEXT,\n  note          TEXT,\n  UNIQUE (agreement_id, code, from_date)\n);\nCREATE INDEX idx_service_rate ON service_rate(agreement_id, code, from_date);\n\n-- What the case cost, beside what it was sold for.\nALTER TABLE referral ADD COLUMN net_cost INTEGER;\nALTER TABLE referral ADD COLUMN service_code TEXT;\n"],
  ["0014_margin_basis.sql", "-- 0014_margin_basis.sql — SUPERSEDED, kept so history reads straight.\n--\n-- This rebuilt `referral_agreement` to widen a CHECK, with the columns written\n-- out by hand. Another set of migrations had meanwhile added `name_km` to the\n-- same table, and a hand-written column list silently dropped it.\n--\n-- The rebuild now lives in 0017_margin_basis.mjs, which reads the columns the\n-- table actually has instead of assuming them. This file does nothing.\n"],
  ["0014_rate_jurisdiction.sql", "-- 0014_rate_jurisdiction.sql — a rate is unique within its own country.\n--\n-- The table was built when there was one country, so `UNIQUE (scope, code,\n-- from_date)` was right: one VAT rate starting on one date. With books kept\n-- under two sets of law in the same file, Cambodia's 10% and Thailand's 7% are\n-- both `vat/standard` from the same day, and the constraint refused the second\n-- one. The jurisdiction joins the key.\n\nPRAGMA foreign_keys = OFF;\n\nCREATE TABLE rate_new (\n  id            TEXT PRIMARY KEY,\n  jur           TEXT NOT NULL DEFAULT 'TH',\n  scope         TEXT NOT NULL,\n  code          TEXT NOT NULL,\n  value_bp      INTEGER,\n  value_satang  INTEGER,\n  from_date     TEXT NOT NULL,\n  to_date       TEXT,\n  source        TEXT,\n  UNIQUE (jur, scope, code, from_date)\n);\n\nINSERT INTO rate_new (id, jur, scope, code, value_bp, value_satang, from_date, to_date, source)\nSELECT id, COALESCE(jur,'TH'), scope, code, value_bp, value_satang, from_date, to_date, source\n  FROM rate;\n\nDROP TABLE rate;\nALTER TABLE rate_new RENAME TO rate;\nCREATE INDEX IF NOT EXISTS idx_rate_jur ON rate(jur, scope, code, from_date);\n\nPRAGMA foreign_keys = ON;\n"],
  ["0015_doc_vat_rate.sql", "-- 0015_doc_vat_rate.sql — a document remembers the rate it was charged at.\n--\n-- The renderer printed \"VAT 7%\" because seven was written into the template. A\n-- Cambodian invoice is ten, and a Thai one reprinted after a rate change is\n-- whatever it was on the day. The rate belongs on the document, beside the\n-- amount it produced.\n\nALTER TABLE doc ADD COLUMN vat_bp INTEGER NOT NULL DEFAULT 0;\n"],
  ["0016_places.sql", "-- 0016_places.sql — the ways in and the ways to be paid are not the same in\n-- every country.\n--\n-- Two enumerations were written from Chiang Mai. In Phnom Penh the chat people\n-- actually use is Telegram, and the scan-to-pay standard is KHQR through\n-- Bakong rather than PromptPay. The kinds widen: 'chat' for any messenger, and\n-- 'qr' for a scan-to-pay code whose payload the bank issues rather than this\n-- system generating it.\n--\n-- Nothing is renamed. Rows already written as 'line' or 'promptpay' stay as\n-- they are: they were true when they were written, and the labels people see\n-- come from the row's own label, not from the kind.\n\nPRAGMA foreign_keys = OFF;\n\nCREATE TABLE intake_channel_new (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  kind          TEXT NOT NULL CHECK (kind IN ('link','email','line','chat','slip')),\n  address       TEXT NOT NULL,\n  label         TEXT,\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  UNIQUE (entity_id, kind, address)\n);\nINSERT INTO intake_channel_new SELECT id, entity_id, kind, address, label, is_active, created_at\n  FROM intake_channel;\nDROP TABLE intake_channel;\nALTER TABLE intake_channel_new RENAME TO intake_channel;\nCREATE INDEX IF NOT EXISTS idx_channel_entity ON intake_channel(entity_id, is_active);\n\nCREATE TABLE pay_method_new (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  kind          TEXT NOT NULL\n                CHECK (kind IN ('promptpay','qr','bank','cash','link','other')),\n  label_en      TEXT NOT NULL,\n  label_th      TEXT,\n  label_km      TEXT,\n  payee_id      TEXT,\n  bank_name     TEXT,\n  account_name  TEXT,\n  account_no    TEXT,\n  link_template TEXT,\n  -- A QR whose payload the bank gave you: stored as the string it encodes, so\n  -- the page can draw it. This system does not invent a payment payload it\n  -- cannot verify.\n  qr_payload    TEXT,\n  account_code  TEXT NOT NULL DEFAULT '1010',\n  direction     TEXT NOT NULL DEFAULT 'in' CHECK (direction IN ('in','out','both')),\n  is_default    INTEGER NOT NULL DEFAULT 0,\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  sort          INTEGER NOT NULL DEFAULT 0,\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\nINSERT INTO pay_method_new (id, entity_id, kind, label_en, label_th, label_km, payee_id,\n  bank_name, account_name, account_no, link_template, account_code, direction,\n  is_default, is_active, sort, note, created_at)\nSELECT id, entity_id, kind, label_en, label_th, label_km, payee_id,\n  bank_name, account_name, account_no, link_template, account_code, direction,\n  is_default, is_active, sort, note, created_at FROM pay_method;\nDROP TABLE pay_method;\nALTER TABLE pay_method_new RENAME TO pay_method;\nCREATE INDEX IF NOT EXISTS idx_paymethod_entity ON pay_method(entity_id, direction, is_active);\n\nPRAGMA foreign_keys = ON;\n\n-- An arrival records which way it came in, and 'chat' is now one of them.\nPRAGMA foreign_keys = OFF;\n\nCREATE TABLE inbox_item_new (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  channel_id    TEXT REFERENCES intake_channel(id) ON DELETE SET NULL,\n  source        TEXT NOT NULL DEFAULT 'link'\n                CHECK (source IN ('link','email','line','chat','slip','manual')),\n  received_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  on_date       TEXT,\n  from_ref      TEXT,\n  kind          TEXT NOT NULL DEFAULT 'unknown'\n                CHECK (kind IN ('bill','invoice','payment','unknown')),\n  description   TEXT,\n  amount        INTEGER,\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  vat           INTEGER,\n  tax_id        TEXT,\n  slip_ref      TEXT,\n  party_id      TEXT REFERENCES party(id),\n  party_hint    TEXT,\n  account_hint  TEXT,\n  confidence    INTEGER NOT NULL DEFAULT 0,\n  photo_name    TEXT,\n  photo_data    TEXT,\n  status        TEXT NOT NULL DEFAULT 'new'\n                CHECK (status IN ('new','used','dismissed')),\n  doc_id        TEXT REFERENCES doc(id) ON DELETE SET NULL,\n  payment_id    TEXT REFERENCES payment(id) ON DELETE SET NULL,\n  dismissed_why TEXT,\n  note          TEXT,\n  idem_key      TEXT UNIQUE\n);\nINSERT INTO inbox_item_new SELECT id, entity_id, channel_id, source, received_at, on_date,\n  from_ref, kind, description, amount, currency, vat, tax_id, slip_ref, party_id,\n  party_hint, account_hint, confidence, photo_name, photo_data, status, doc_id,\n  payment_id, dismissed_why, note, idem_key FROM inbox_item;\nDROP TABLE inbox_item;\nALTER TABLE inbox_item_new RENAME TO inbox_item;\nCREATE INDEX IF NOT EXISTS idx_inbox_entity ON inbox_item(entity_id, status, received_at DESC);\n\nPRAGMA foreign_keys = ON;\n"],
  ["0017_margin_basis.mjs", step0],
  ["0018_margin_flow.sql", "-- 0018_margin_flow.sql — the client on a resold case.\n--\n-- A margin arrangement has two documents, not one: the client is invoiced at\n-- the price they were quoted, and the desk that does the work bills at the net\n-- price. The difference is gross profit that falls out of the books rather than\n-- a commission anyone has to invoice for.\n--\n-- So a case has to know whose case it is. A commission arrangement does not\n-- need this — the other desk holds the client — which is why it is a column\n-- rather than a requirement.\n\nALTER TABLE referral ADD COLUMN client_party_id TEXT REFERENCES party(id);\nALTER TABLE referral ADD COLUMN client_doc_id TEXT REFERENCES doc(id);\nALTER TABLE referral ADD COLUMN net_doc_id TEXT REFERENCES doc(id);\n"],
  ["0019_crypto.sql", "-- 0019_crypto.sql — digital assets, held and moved like anything else.\n--\n-- The accounting question is settled before the technology: A COIN IS NOT CASH.\n-- It is an asset held at what it cost, and the difference between that and what\n-- it is worth today is not income until it is sold or spent. So a wallet gets\n-- its own asset account, receipts are booked at the rate on the day, and a\n-- disposal realises the difference into one account where it can be seen.\n--\n-- Amounts are integers in the asset's own minor unit — satoshi, or the six\n-- decimals a dollar stablecoin uses — for the same reason baht are satang. An\n-- eighteen-decimal chain is stored to nine and says so, because a JavaScript\n-- integer stops being exact above that and a silently wrong balance is worse\n-- than a stated limit.\n--\n-- What this file does NOT do is decide anyone's tax. Whether a gain is income,\n-- what is withheld and when, is a question for the person who signs the return;\n-- the rate rows are here to be filled in, not guessed.\n\nCREATE TABLE wallet (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  label         TEXT NOT NULL,\n  asset         TEXT NOT NULL,              -- 'BTC','USDT','USDC','ETH'\n  network       TEXT,                       -- 'bitcoin','tron','ethereum','solana'\n  address       TEXT,\n  -- Its own account in the chart, so the books show what is held where.\n  account_code  TEXT NOT NULL,\n  -- Held for the business, or a customer's own wallet we pay out to.\n  direction     TEXT NOT NULL DEFAULT 'in' CHECK (direction IN ('in','out','both')),\n  is_default    INTEGER NOT NULL DEFAULT 0,\n  is_active     INTEGER NOT NULL DEFAULT 1,\n  note          TEXT,\n  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  UNIQUE (entity_id, label)\n);\nCREATE INDEX idx_wallet_entity ON wallet(entity_id, is_active);\n\n-- What an asset was worth, on a day. Dated rows like every other rate in this\n-- system, with where the number came from, because \"the price of bitcoin\" is\n-- a quote from somewhere at a moment and a year later that matters.\nCREATE TABLE asset_rate (\n  id            TEXT PRIMARY KEY,\n  asset         TEXT NOT NULL,\n  quote         TEXT NOT NULL DEFAULT 'THB',\n  -- Units of `quote` per ONE whole unit of `asset`, in parts per million, so\n  -- ฿36.25 to a dollar is 36_250_000 and no float is stored.\n  rate_ppm      INTEGER NOT NULL,\n  on_date       TEXT NOT NULL,\n  source        TEXT,\n  UNIQUE (asset, quote, on_date)\n);\nCREATE INDEX idx_asset_rate ON asset_rate(asset, quote, on_date DESC);\n\n-- What actually moved on a chain, beside the payment it settled.\nALTER TABLE payment ADD COLUMN asset TEXT;\nALTER TABLE payment ADD COLUMN network TEXT;\nALTER TABLE payment ADD COLUMN asset_amount INTEGER;      -- in the asset's minor unit\nALTER TABLE payment ADD COLUMN asset_rate_ppm INTEGER;    -- the rate it was booked at\nALTER TABLE payment ADD COLUMN tx_ref TEXT;               -- the transaction, as the chain gives it\n"],
  ["0020_currency_banks.sql", "-- 0020_currency_banks.sql — several banks, several currencies, one ledger.\n--\n-- Two things an operator with a Thai bank, a Cambodian bank and a dollar\n-- account needs, and which a currency label alone does not give:\n--\n--   1. AN ACCOUNT KNOWS WHICH BANK IT IS. A row in the chart called \"Bank\n--      account\" is useless when there are five; each carries the bank, the\n--      number and the currency it is held in, so a balance can be read against\n--      a statement.\n--   2. A FOREIGN DOCUMENT POSTS IN THE BOOKS' OWN CURRENCY. An invoice in\n--      dollars is a dollar promise, but the ledger adds up in one currency, so\n--      the rate it was booked at is kept on the document and on the payment\n--      rather than remembered.\n--\n-- The difference between the rate when the invoice was raised and the rate when\n-- it was paid is a real gain or loss, and it is posted on the day of payment\n-- rather than smoothed away.\n\nALTER TABLE account ADD COLUMN bank_name TEXT;\nALTER TABLE account ADD COLUMN account_no TEXT;\nALTER TABLE account ADD COLUMN is_bank INTEGER NOT NULL DEFAULT 0;\nALTER TABLE account ADD COLUMN opened_on TEXT;\n\n-- What a payment came to in the books' own currency, and at what rate.\nALTER TABLE payment ADD COLUMN booked_amount INTEGER;\nALTER TABLE payment ADD COLUMN fx_rate_ppm INTEGER;\n"],
  ["0021_reporting_currency.sql", "-- 0021_reporting_currency.sql — the currency a return is filed in.\n--\n-- Cambodia is the case that makes this necessary: the trade is in dollars, the\n-- books are in dollars, and the General Department of Taxation wants the return\n-- in riel at the official rate. Two currencies, two purposes, and converting\n-- one into the other at filing time is arithmetic that should be recorded\n-- rather than done in someone's head.\n--\n-- Where the two are the same — Thailand — nothing changes.\n\nALTER TABLE entity ADD COLUMN report_currency TEXT;\nALTER TABLE filing ADD COLUMN report_amount INTEGER;      -- what was filed, in that currency\nALTER TABLE filing ADD COLUMN report_rate_ppm INTEGER;    -- and at what rate\n"],
  ["0022_foreign_customers.sql", "-- 0022_foreign_customers.sql — when most of the customers are not from here.\n--\n-- A desk in Chiang Mai whose clients are foreigners has a different shape of\n-- problem from one whose clients are Thai companies:\n--\n--   · the customer reads English and thinks in their own currency\n--   · they pay from abroad, so a transfer needs SWIFT and IBAN, not a\n--     three-part local account number\n--   · they do NOT withhold tax — withholding is what a Thai company does to a\n--     Thai supplier — so defaulting an invoice to 3% withheld is wrong for\n--     nine out of ten of them\n--   · the invoice may be zero-rated as an export of services, which is a\n--     condition to be met rather than a box to tick by default\n--\n-- So the customer carries their own language, their own currency, and how they\n-- are treated for tax; the invoice takes its defaults from them.\n\nALTER TABLE party ADD COLUMN locale TEXT;                 -- what they read\nALTER TABLE party ADD COLUMN withholds INTEGER;           -- 1 = they withhold at source\nALTER TABLE party ADD COLUMN tax_treatment TEXT;          -- 'standard' | 'zero_rated' | 'exempt'\nALTER TABLE party ADD COLUMN note_tax TEXT;               -- why, in one line\n\n-- An account somebody abroad can actually send money to.\nALTER TABLE account ADD COLUMN swift TEXT;\nALTER TABLE account ADD COLUMN iban TEXT;\nALTER TABLE account ADD COLUMN bank_address TEXT;\n\n-- A rate nobody has confirmed yet is usable and says so.\nALTER TABLE rate ADD COLUMN unconfirmed INTEGER NOT NULL DEFAULT 0;\n"],
  ["0023_bringing_in.sql", "-- 0023_bringing_in.sql — moving in from whatever they use now.\n--\n-- The barrier to changing bookkeeping systems is not the software. It is the\n-- four hundred customers, the thirty unpaid invoices and the balance in the\n-- bank, all of which already exist somewhere — an Excel file, an accountant's\n-- export, a bank statement — and none of which anybody wants to retype.\n--\n-- So a table arrives as a paste or a file, is read as it is (Buddhist years,\n-- ฿ signs, Thai column headings, brackets for a credit), and what it produced\n-- is recorded: every row that came in carries the batch it came from, and a\n-- batch that was a mistake can be taken out again while it has touched nothing.\n\nCREATE TABLE import_batch (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  kind          TEXT NOT NULL CHECK (kind IN ('contacts','invoices','bills','statement','items')),\n  source_name   TEXT,                    -- the file it came from, if it had a name\n  at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')),\n  person_id     TEXT REFERENCES person(id),\n  counts        TEXT,                    -- what it made, as JSON\n  note          TEXT\n);\nCREATE INDEX idx_import_entity ON import_batch(entity_id, at DESC);\n\n-- What a row became, so it can be found again and taken back out.\nALTER TABLE party ADD COLUMN import_batch TEXT;\nALTER TABLE doc ADD COLUMN import_batch TEXT;\n\n-- A line off a bank statement. It is not a payment: it is what the bank says\n-- happened, sitting beside the invoices until somebody — or an exact amount\n-- with its own satang tail — says which one it belongs to.\nCREATE TABLE bank_line (\n  id            TEXT PRIMARY KEY,\n  entity_id     TEXT NOT NULL REFERENCES entity(id) ON DELETE CASCADE,\n  account_id    TEXT REFERENCES account(id) ON DELETE SET NULL,\n  batch_id      TEXT REFERENCES import_batch(id) ON DELETE SET NULL,\n  on_date       TEXT NOT NULL,\n  description   TEXT,\n  ref           TEXT,\n  -- Signed, in the account's own currency: money in is positive.\n  amount        INTEGER NOT NULL,\n  currency      TEXT NOT NULL DEFAULT 'THB',\n  balance       INTEGER,\n  status        TEXT NOT NULL DEFAULT 'new'\n                CHECK (status IN ('new','matched','ignored')),\n  payment_id    TEXT REFERENCES payment(id) ON DELETE SET NULL,\n  doc_id        TEXT REFERENCES doc(id) ON DELETE SET NULL,\n  -- The same file imported twice adds nothing: a line is its account, its date,\n  -- its amount, its description and the running balance beside it.\n  fingerprint   TEXT UNIQUE,\n  imported_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now'))\n);\nCREATE INDEX idx_bankline_entity ON bank_line(entity_id, status, on_date);\n"],
  ["0024_filing_posts.sql", "-- 0024_filing_posts.sql — a return that is filed does something to the books.\n--\n-- Until now, marking a return filed wrote a receipt number and nothing else.\n-- Output VAT, input VAT, withholding and social security therefore grew month\n-- after month with no way to clear them, and the payment that leaves the bank\n-- on the 15th had nothing in the books to belong to — so it sat in the\n-- statement forever as a line nobody could place.\n--\n-- Filing now NETS the period into one figure owed to the office, and paying it\n-- is its own act on its own day, because that is how the money actually moves.\n-- Both leave a journal, and the filing remembers which.\n\nALTER TABLE filing ADD COLUMN settled_journal_id TEXT REFERENCES journal(id);\nALTER TABLE filing ADD COLUMN payment_journal_id TEXT REFERENCES journal(id);\nALTER TABLE filing ADD COLUMN paid_on TEXT;\nALTER TABLE filing ADD COLUMN paid_from TEXT;          -- the account it left\n\n-- A statement line can settle a return, not only an invoice.\nALTER TABLE bank_line ADD COLUMN filing_id TEXT REFERENCES filing(id) ON DELETE SET NULL;\n"],
]
